import type { NormalizedModelBenchmark } from "@lite-llm/contracts/benchmarks";

export interface IBenchmarksRepository {
  upsert(models: NormalizedModelBenchmark[]): Promise<void>;
  getAll(): Promise<NormalizedModelBenchmark[]>;
  getByAaModelId(aaModelId: string): Promise<NormalizedModelBenchmark | null>;
  count(): Promise<number>;
  clear(): Promise<void>;
}

import { db, modelProxyBenchmarks } from "@lite-llm/database";
import { eq } from "drizzle-orm";
import type { IBenchmarksRepository } from "./interfaces";
import type { NormalizedModelBenchmark } from "@lite-llm/contracts/benchmarks";

export class DbBenchmarksRepository implements IBenchmarksRepository {
  async upsert(models: NormalizedModelBenchmark[]): Promise<void> {
    await db.transaction(async (tx) => {
      for (const m of models) {
        await tx.insert(modelProxyBenchmarks).values(toRow(m))
          .onConflictDoUpdate({
            target: modelProxyBenchmarks.aaModelId,
            set: toRow(m),
          });
      }
    });
  }

  async getAll(): Promise<NormalizedModelBenchmark[]> {
    const rows = await db.select().from(modelProxyBenchmarks);
    return rows.map(fromRow);
  }

  async getByAaModelId(aaModelId: string): Promise<NormalizedModelBenchmark | null> {
    const rows = await db.select().from(modelProxyBenchmarks).where(eq(modelProxyBenchmarks.aaModelId, aaModelId)).limit(1);
    return rows.length > 0 ? fromRow(rows[0]) : null;
  }

  async count(): Promise<number> {
    const rows = await db.select().from(modelProxyBenchmarks);
    return rows.length;
  }

  async clear(): Promise<void> {
    await db.delete(modelProxyBenchmarks);
  }
}

